#!/bin/sh
set -eu

# Only device builds with dSYMs need symbol uploads
if [ "$PLATFORM_NAME" != "iphoneos" ] || [ "$DEBUG_INFORMATION_FORMAT" != "dwarf-with-dsym" ]; then
  exit 0
fi

crashlytics_dir="${BUILD_DIR%Build/*}/SourcePackages/checkouts/firebase-ios-sdk/Crashlytics"

# Upload native symbols using the Firebase Swift package
/bin/bash "$crashlytics_dir/run"

# Include the Dart AOT symbols generated by Flutter when available
flutter_dsym="$BUILT_PRODUCTS_DIR/App.framework.dSYM"
if [ -d "$flutter_dsym" ]; then
  firebase_plist="$TARGET_BUILD_DIR/$UNLOCALIZED_RESOURCES_FOLDER_PATH/GoogleService-Info.plist"
  firebase_app_id=$(/usr/libexec/PlistBuddy -c 'Print :GOOGLE_APP_ID' "$firebase_plist")
  /bin/bash "$crashlytics_dir/run" -ai "$firebase_app_id" -- "$flutter_dsym"
fi
